const updateAgentSkill = `-- name: UpdateAgentSkill :execrows
UPDATE agent_skills SET enabled = $1, version_id = $2, revision = revision + 1, updated_at = now()
WHERE company_id = $3 AND agent_id = $4 AND id = $5 AND revision = $6
`

type UpdateAgentSkillParams struct {
	Enabled   bool      `json:"enabled"`
	VersionID uuid.UUID `json:"version_id"`
	CompanyID uuid.UUID `json:"company_id"`
	AgentID   uuid.UUID `json:"agent_id"`
	ID        uuid.UUID `json:"id"`
	Revision  int64     `json:"revision"`
}

func (q *Queries) UpdateAgentSkill(ctx context.Context, arg UpdateAgentSkillParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateAgentSkill,
		arg.Enabled,
		arg.VersionID,
		arg.CompanyID,
		arg.AgentID,
		arg.ID,
		arg.Revision,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
